package sohal.lld.battleship.ship;import sohal.lld.battleship.model.Coord;import java.util.Collections;import java.util.HashSet;import java.util.Set;public class SquareShip implements Ship {    private final String id;    private final int size;    private final Set<Coord> cells;    private boolean destroyed = false;    public SquareShip(String id, int size, Set<Coord> cells) {        this.id = id;        this.size = size;        this.cells = Collections.unmodifiableSet(new HashSet<>(cells));    }    @Override public String getId() { return id; }    @Override public Set<Coord> getCells() { return cells; }    @Override public boolean isDestroyed() { return destroyed; }    @Override public void destroy() { destroyed = true; }}